"""
    format 1-2-3... to 00001-00002-00003...
    src should be convertable to int
    """
def sort_format(src: Any) -> object {
    src_list = src.split('-');
    res_list = [];
    for elm in src_list {
        try {
            res_list.append(('%05d' % int(elm)));
        } except Exception as e {
            res_list.append(elm);
        }
    }
    res = '-'.join(res_list);
    return res;
}

"""
    :type content: dict
    :param content: A dictionary as returned by KairosDB with timestamps converted to seconds since the epoch

    :type name: str
    :param name: The name of the entry in the results whose values will be returned

    :rtype: list
    :return: a list of resulting [timestamp, value] pairs

    When you've got content, but only want to look at a piece of it,
    specifically the values that are provided for a particular name, then use
    this function.

    return the dict(s) whose name matches the argument "name"

    """
def get_content_values_by_name(content: Any, name: Any) -> object {
    r_list = `list();
    for q in content["queries"] {
        for r in q["results"] {
            if (r["name"] == name) {
                r_list.append(r);
            }
        }
    }
    return r_list;
}

"""
    recover "17" to 17.
    recover "[]" to [].
    recover "datetime(2020,1,1)" to datetime(2020,1,1).
    keep "abc" as str.

    :param v: str.
    :return: Any.
    """
def _recover_type(v: Any) -> object {
    try {
        nv = eval(v);
    } except (NameError, SyntaxError) {
        nv = v;
    }
    if callable(nv) {
        nv = v;
    }
    return nv;
}

